import json
d=json.load(open('runs/candidates/c001/feedback.json'))
def walk(o,p=""):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,p+"/"+k)
    elif isinstance(o,list):
        for i,v in enumerate(o[:2]): walk(v,p+f"[{i}]")
    else:
        s=str(o)
        if any(t in s.lower() for t in ("error","trace","exception","fail","stderr","assert")) and len(s)>0:
            print(p,"=>",s[:300])
walk(d)
print("=== top-level keys ===", list(d.keys()))
